 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    objects = []
    seen = set()
    # Find monochrome filled 3x3 blocks.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            if all(grid[rr][cc] == color for rr in range(r, r + 3) for cc in range(c, c + 3)):
                objects.append((r + 1, c + 1, color))
                seen.update((rr, cc) for rr in range(r, r + 3) for cc in range(c, c + 3))
    # Project each block's center row and column. Different projected colors
    # meeting on an originally empty cell cancel at that crossing.
    lines = {}
    for cr, cc, color in objects:
        for x in range(w):
            lines.setdefault((cr, x), set()).add(color)
        for y in range(h):
            lines.setdefault((y, cc), set()).add(color)
    for (r, c), colors in lines.items():
        if grid[r][c] != 0:
            continue
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
